entries[76047] = { ["name"] = "Dunkler Spalt", ["text"] = "Wirken in 2 sek.\nSchlägt auf den Boden vor dem Zaubernden und fügt so allen Gegnern im Umkreis von 1 Metern um den Einschlagsort 56550 to 63450 Schattenschaden zu. Zusätzlich öffnet sich ein dunkler Spalt am Zielort, der Feinden im Umkreis von 6 Metern pro Sekunde 9425 to 10575 Schattenschaden zufügt. Die Größe von dunklen Spalten nimmt mit der Zeit zu. Hält 60 Sek. lang an." }
